CREATE OR REPLACE FUNCTION public.fn_financial_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old jsonb; v_new jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'UPDATE' THEN v_old := to_jsonb(OLD); v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'DELETE' THEN v_old := to_jsonb(OLD);
  END IF;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES (TG_TABLE_NAME, COALESCE((NEW).id, (OLD).id), TG_OP, v_old, v_new, auth.uid());

  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION public.fn_recalc_payable_installment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inst public.accounts_payable_installments%ROWTYPE;
  v_total_pago numeric(14,2);
  v_total_desc numeric(14,2);
  v_total_juros numeric(14,2);
  v_total_multa numeric(14,2);
  v_status text;
  v_inst_id uuid := COALESCE(NEW.installment_id, OLD.installment_id);
  v_parent_id uuid;
  v_open int; v_partial int; v_paid int; v_canc int; v_total int;
BEGIN
  SELECT * INTO v_inst FROM public.accounts_payable_installments WHERE id = v_inst_id;
  IF NOT FOUND THEN RETURN COALESCE(NEW, OLD); END IF;

  SELECT COALESCE(SUM(amount_paid),0), COALESCE(SUM(discount_amount),0),
         COALESCE(SUM(interest_amount),0), COALESCE(SUM(penalty_amount),0)
    INTO v_total_pago, v_total_desc, v_total_juros, v_total_multa
    FROM public.payable_payments WHERE installment_id = v_inst_id;

  IF (v_total_pago + v_total_desc) >= (v_inst.original_amount + v_total_juros + v_total_multa) THEN v_status := 'PAID';
  ELSIF v_total_pago > 0 THEN v_status := 'PARTIAL';
  ELSE v_status := CASE WHEN v_inst.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date THEN 'OVERDUE' ELSE 'OPEN' END;
  END IF;

  UPDATE public.accounts_payable_installments
    SET paid_amount = v_total_pago, discount_amount = v_total_desc,
        interest_amount = v_total_juros, penalty_amount = v_total_multa,
        status = v_status,
        paid_at = CASE WHEN v_status='PAID' THEN now() ELSE NULL END
    WHERE id = v_inst_id;

  v_parent_id := v_inst.payable_id;
  SELECT count(*) FILTER (WHERE status='OPEN'),
         count(*) FILTER (WHERE status='PARTIAL'),
         count(*) FILTER (WHERE status='PAID'),
         count(*) FILTER (WHERE status='CANCELED'),
         count(*)
    INTO v_open, v_partial, v_paid, v_canc, v_total
    FROM public.accounts_payable_installments WHERE payable_id = v_parent_id;

  UPDATE public.accounts_payable SET status = CASE
    WHEN v_canc = v_total THEN 'CANCELED'
    WHEN (v_paid + v_canc) = v_total AND v_paid > 0 THEN 'PAID'
    WHEN v_paid > 0 OR v_partial > 0 THEN 'PARTIAL'
    WHEN EXISTS (SELECT 1 FROM public.accounts_payable_installments WHERE payable_id = v_parent_id AND status='OVERDUE') THEN 'OVERDUE'
    ELSE 'OPEN'
  END WHERE id = v_parent_id AND status <> 'CANCELED';

  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION public._saas_trg_require_feature()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_key text := TG_ARGV[0];
BEGIN
  IF v_uid IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    JOIN public.organizations o ON o.id = p.organization_id AND o.ativo IS TRUE
    WHERE p.user_id = v_uid AND p.ativo IS TRUE AND p.organization_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'saas_context_unavailable: usuário ativo e empresa são obrigatórios'
      USING ERRCODE = '42501';
  END IF;
  IF NOT public._saas_user_has_feature(v_uid, v_key) THEN
    RAISE EXCEPTION 'saas_feature_not_entitled: funcionalidade não contratada ou assinatura indisponível'
      USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_set_initial_next_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_initial DATE;
BEGIN
  IF NEW.next_generation_date IS NULL THEN
    v_initial := NEW.start_date;
    IF NEW.due_day IS NOT NULL AND NEW.recurrence_frequency IN ('MONTHLY','QUARTERLY','YEARLY') THEN
      BEGIN
        v_initial := make_date(EXTRACT(YEAR FROM v_initial)::INT, EXTRACT(MONTH FROM v_initial)::INT,
          LEAST(NEW.due_day, EXTRACT(DAY FROM (date_trunc('month', v_initial) + INTERVAL '1 month - 1 day'))::INT));
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;
    NEW.next_generation_date := v_initial;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_recurring_template_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_action := 'RECURRING_TEMPLATE_CREATED';
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by)
    VALUES ('RECURRING_TEMPLATE', NEW.id, v_action, to_jsonb(NEW), auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    IF OLD.active = true AND NEW.active = false AND NEW.end_date IS NOT NULL AND (OLD.end_date IS NULL OR OLD.end_date <> NEW.end_date) THEN
      v_action := 'RECURRING_TEMPLATE_CLOSED';
    ELSIF OLD.active = true AND NEW.active = false THEN
      v_action := 'RECURRING_TEMPLATE_PAUSED';
    ELSIF OLD.active = false AND NEW.active = true THEN
      v_action := 'RECURRING_TEMPLATE_REACTIVATED';
    ELSE
      v_action := 'RECURRING_TEMPLATE_UPDATED';
    END IF;
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, old_data, new_data, performed_by)
    VALUES ('RECURRING_TEMPLATE', NEW.id, v_action, to_jsonb(OLD), to_jsonb(NEW), auth.uid());
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, old_data, performed_by)
    VALUES ('RECURRING_TEMPLATE', OLD.id, 'RECURRING_TEMPLATE_DELETED', to_jsonb(OLD), auth.uid());
    RETURN OLD;
  END IF;
  RETURN NULL;
END $function$
